function renderSourceCoverage(){return `<section class="reference-prose gf-scope-notes" id="guide-source-coverage"><h2>What the guide carries forward from the sources</h2><p>The reading-first revision checks the substantive guidance against all four supplied documents and the original workflow discussion. The entries below identify where that guidance appears without a required activity. The original source documents are not reproduced in full.</p>${SOURCE_COVERAGE.map(r=>`<div class="gf-coverage-row"><small>${esc(r[0])} · ${esc(r[1])}</small><h3>${esc(r[2])}</h3><p>${r[3].split('; ').map(c=>`<a class="inline-link" href="${['questions','glossary','sources'].includes(c)?'#/'+c:'#/read/'+c}">${esc(c==='harness'?'Organize the materials':CHAPTERS.find(x=>x.id===c)?.nav||c)}</a>`).join(' · ')}. ${esc(r[5])}.</p></div>`).join('')}<h2>Editorial distinctions and limits</h2>${EDITORIAL_DECISIONS.map(t=>`<p>${esc(t)}</p>`).join('')}<h3>Further-reading leads retained from the introductory guide</h3><p>The introductory source points to Ethan Mollick’s <em>Co-Intelligence</em> and <em>One Useful Thing</em>, Andrej Karpathy’s lectures, Anthropic’s prompting documentation, the AI Hallucination Cases Database, ABA Formal Opinion 512, and Bob Ambrogi’s <em>LawSites</em>. These are the author’s source reading leads, not a newly verified ranking of current resources.</p></section>`;}
function guideContents(compact=false){return `<div class="gf-contents ${compact?'gf-contents-home':''}">${PARTS.map((p,i)=>`<section class="gf-content-part" id="part-${i}"><header><span class="eyebrow">Part ${roman[i]}</span><h2>${p.name}</h2><p>${p.desc}</p></header><div>${CHAPTERS.map((c,n)=>c.part===i?`<a class="gf-content-chapter" href="#/read/${c.id}"><span class="gf-chapter-number">${num(n+1)}</span><div><h3>${c.title}</h3><p>${c.desc}</p></div><span class="gf-chapter-arrow">${icon(state.done.includes(c.id)?'check':'arrow')}</span></a>`:'').join('')}</div></section>`).join('')}</div>`;}

function renderQuestions(){return `<div class="page gf-questions-page"><header class="page-heading"><span class="eyebrow">A reference for continued thinking</span><h1>Questions for the profession</h1><p>These questions collect the broader inquiry in the two source guides. They are open questions about what legal work should become, not statements of settled law or an answer key. Read them by subject or return when experience gives you another way to think about one.</p><p class="small muted">Minor punctuation and typographical edits have been made. The complete explanations in the chapters do not depend on writing a response.</p></header><nav class="gf-part-links" aria-label="Question subjects">${READING_QUESTIONS.map((g,i)=>`<a href="#/questions?group=${i}">${g[0]}</a>`).join('')}</nav><div class="reference-prose gf-question-groups">${READING_QUESTIONS.map((g,i)=>`<section id="questions-${i}"><span class="eyebrow">${esc(g[1])}</span><h2>${g[0]}</h2>${g[2].map((q,j)=>`<p class="gf-open-question"><span aria-hidden="true">${num(j+1)}</span>${esc(q)}</p>`).join('')}</section>`).join('')}</div><aside class="gf-companion-footer"><p>The optional <a href="#/lab/reflection">reflection worksheet</a> retains the earlier selection of questions and your saved responses. The collection above is the complete readable reference.</p></aside>${footer()}</div>`;}

/* The AI-Enabled Lawyer: static client-side reader. No external requests, AI calls, or telemetry. */
const APP_KEY='regalia-field-guide.v1';
const DEFAULT_STATE={version:1,done:[],bookmarks:[],favorites:[],fields:{},quiz:{},theme:'light',font:17,focus:false,motion:false,last:''};
let storageOK=true;
function safeState(raw){
 const s={...DEFAULT_STATE,fields:{},quiz:{},done:[],bookmarks:[],favorites:[]};
 if(!raw||typeof raw!=='object')return s;
 ['done','bookmarks'].forEach(k=>{if(Array.isArray(raw[k]))s[k]=[...new Set(raw[k].filter(id=>CHAPTERS.some(c=>c.id===id)))];});
 if(Array.isArray(raw.favorites))s.favorites=[...new Set(raw.favorites.filter(id=>PROMPTS.some(p=>p.id===id)))];
 if(raw.fields&&typeof raw.fields==='object'&&!Array.isArray(raw.fields))Object.entries(raw.fields).forEach(([k,v])=>{if(/^[a-z][a-z0-9:_-]{0,130}$/i.test(k)&&!['__proto__','constructor','prototype'].includes(k)&&(typeof v==='string'||typeof v==='boolean'))s.fields[k]=typeof v==='string'?v.slice(0,100000):v;});
 if(raw.quiz&&typeof raw.quiz==='object')Object.entries(raw.quiz).forEach(([k,v])=>{if(CHAPTERS.some(c=>c.id===k)&&Number.isInteger(v)&&v>=0&&v<3)s.quiz[k]=v;});
 s.theme=raw.theme==='dark'?'dark':'light';s.font=[16,17,19].includes(raw.font)?raw.font:17;s.focus=raw.focus===true;s.motion=raw.motion===true;s.last=CHAPTERS.some(c=>c.id===raw.last)?raw.last:'';
 return s;
}
let state;
try{state=safeState(JSON.parse(localStorage.getItem(APP_KEY)||'null'));localStorage.setItem(APP_KEY,JSON.stringify(state));}catch(e){state=safeState(null);storageOK=false;}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const strip=x=>{const d=document.createElement('div');d.innerHTML=x;return d.textContent.replace(/\s+/g,' ').trim();};
const slug=x=>x.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const num=n=>String(n).padStart(2,'0');
const roman=['I','II','III','IV'];
