function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.book}</svg>`;}
function saveState(){try{localStorage.setItem(APP_KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}updateStorageWarning();updateProgress();}
function setField(key,value){state.fields[key]=value;saveState();}
function value(key){return state.fields[key]??'';}
function field(key,title,placeholder='',options={}){FIELD_LABELS[key]=title;const id=`field-${key}`,hint=options.hint||placeholder;const help=FIELD_EXAMPLES[key]?`<button type="button" class="help-dot" data-help="field:${esc(key)}" data-tip="${esc(FIELD_EXAMPLES[key])}" aria-label="Example for ${esc(title)}" aria-haspopup="dialog">?</button>`:'';return `<div class="field ${options.full?'full':''}"><div class="field-label-row"><label for="${id}">${esc(title)}</label>${help}</div>${hint?`<small id="hint-${key}">${esc(hint)}</small>`:''}${options.input?`<input id="${id}" type="text" data-save="${esc(key)}" ${hint?`aria-describedby="hint-${key}"`:''} placeholder="Write here…" maxlength="12000" value="${esc(value(key))}">`:`<textarea id="${id}" data-save="${esc(key)}" ${hint?`aria-describedby="hint-${key}"`:''} class="${options.large?'large':''}" placeholder="Write here…" maxlength="40000">${esc(value(key))}</textarea>`}</div>`;}
function selectField(key,title,choices){FIELD_LABELS[key]=title;SELECT_CHOICES[key]=Object.fromEntries(choices);return `<label class="field" for="field-${key}"><span>${esc(title)}</span><select id="field-${key}" data-save="${key}">${choices.map(([v,t])=>`<option value="${esc(v)}" ${String(value(key))===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function checkField(key,title,hint=''){FIELD_LABELS[key]=title;return `<label class="check-row"><input type="checkbox" data-check="${esc(key)}" ${value(key)===true?'checked':''}><span>${esc(title)}${hint?`<small>${esc(hint)}</small>`:''}</span></label>`;}
function sourceLine(id){const s=SOURCES.find(s=>s.id===id);return s?s.short:'Teaching adaptation';}
function sourceChips(c){return `<div class="source-chips" aria-label="Chapter sources">${c.sources.map(([id,pages])=>`<a href="#/sources?source=${id}" title="View source notes">${esc(sourceLine(id))} · ${esc(pages)}</a>`).join('')}</div>`;}
function footer(){return `<footer class="footer wl-footer"><div><a href="https://write.law/" target="_blank" rel="noopener noreferrer" aria-label="Visit Write.law"><img class="wl-footer-logo" src="data:image/png;base64," alt="Write.law" width="127" height="30"></a><p>The AI-Enabled Lawyer<br>By Joe Regalia · Write.law</p></div><div><a href="#/sources">Sources and teaching notes</a><a href="#/help?topic=saving">Privacy and saved work</a><span>Public edition · September 2026</span></div></footer>`;}
function applyPreferences(){document.documentElement.dataset.theme=state.theme;document.documentElement.style.setProperty('--reading',`${state.font}px`);document.body.classList.toggle('reader-focus',state.focus&&currentRoute.type==='read');document.body.classList.toggle('reduce-motion',state.motion);const theme=document.querySelector('[data-action=theme]');if(theme){theme.innerHTML=icon(state.theme==='dark'?'sun':'moon');theme.setAttribute('aria-label',state.theme==='dark'?'Use light theme':'Use dark theme');}const focus=document.querySelector('[data-action=focus]');if(focus){focus.setAttribute('aria-pressed',String(state.focus));focus.setAttribute('aria-label',state.focus?'Exit focused reading':'Use focused reading');}const font=document.querySelector('[data-action=font]');if(font)font.setAttribute('aria-label',`Change reading text size. Current size ${state.font} pixels.`);}
function renderSidebar(){
 const active=currentRoute.type==='read'?'chapters':currentRoute.type==='lab'?(resourceIsExercise({id:currentRoute.id})?'labs':'templates'):currentRoute.type==='prompts'?'templates':currentRoute.type;
 const item=(href,label,ico,key)=>`<a class="nav-item primary-nav" href="${href}" ${active===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`;
 const companions=['labs','templates','notebook'].includes(active);
 document.getElementById('sidebar').innerHTML=`<a href="#/" class="brand wl-brand" aria-label="Write.law AI guide home"><img class="wl-logo" src="data:image/png;base64," alt="Write.law" width="170" height="40"><span class="wl-guide-name">The AI-Enabled Lawyer</span><span class="brand-sub">A guide by Joe Regalia</span></a><button class="side-search" data-action="search">${icon('search')}<span>Search the guide</span><kbd>⌘ K</kbd></button><nav class="side-scroll" aria-label="Guide navigation">${item('#/','About the guide','home','home')}${item('#/chapters','Contents','book','chapters')}<div class="gf-nav-reading" aria-label="Read the guide">${PARTS.map((p,i)=>`<section class="gf-nav-part"><h2>${p.name}</h2>${CHAPTERS.map((c,n)=>c.part===i?`<a class="nav-item chapter-nav-link" href="#/read/${c.id}" ${currentChapter===c.id?'aria-current="page"':''}><span class="num">${num(n+1)}</span><span>${c.nav}</span></a>`:'').join('')}</section>`).join('')}</div><div class="nav-divider"></div><div class="gf-nav-label">Reference</div>${item('#/glossary','Glossary','search','glossary')}${item('#/questions','Questions for the profession','book','questions')}<details class="gf-companion-nav" ${companions?'open':''}><summary>Optional companion resources</summary>${item('#/labs','Exercises','pen','labs')}${item('#/templates','Templates & worksheets','list','templates')}${item('#/notebook','My saved work','note','notebook')}</details><div class="nav-divider"></div>${item('#/help','Help with the guide','info','help')}${item('#/sources','Sources and editorial notes','layers','sources')}</nav><div class="side-bottom"><div class="progress-label"><span>Your reading</span><span id="progress-text">${state.done.length} / ${CHAPTERS.length}</span></div><div class="progress-track" role="progressbar" aria-label="Chapters marked as read" aria-valuemin="0" aria-valuemax="${CHAPTERS.length}" aria-valuenow="${state.done.length}"><div class="progress-fill" style="width:${state.done.length/CHAPTERS.length*100}%"></div></div><a class="small side-save-note" href="#/help?topic=saving">Progress and notes stay in this browser.</a></div>`;
}
function updateProgress(){const text=document.getElementById('progress-text');if(text)text.textContent=`${state.done.length} / ${CHAPTERS.length}`;const fill=document.querySelector('.progress-fill');if(fill)fill.style.width=`${state.done.length/CHAPTERS.length*100}%`;document.querySelector('.progress-track')?.setAttribute('aria-valuenow',state.done.length);}
function updateStorageWarning(){const w=document.getElementById('storage-warning');if(w){w.hidden=storageOK;w.textContent='Browser storage is unavailable. Your work is kept only for this session. Export your notebook before leaving.';}}
function renderTopbar(){
 const c=CHAPTERS.find(c=>c.id===currentChapter),l=LABS.find(l=>l.id===currentRoute.id);
 const title=c?c.nav:({home:'About the guide',chapters:'Contents',labs:'Exercises',lab:l?.title||'Activity',templates:'Templates & worksheets',prompts:'Prompt templates',glossary:'Glossary',notebook:'My saved work',sources:'Sources',questions:'Questions for the profession',help:'How to use this guide'})[currentRoute.type]||'Guide';
 const parent=c?['#/chapters','Chapters']:currentRoute.type==='lab'?(resourceIsExercise(l||{id:''})?['#/labs','Exercises']:['#/templates','Templates & worksheets']):['#/','Guide'];
 document.getElementById('topbar').innerHTML=`<div class="between" style="min-width:0;gap:10px"><button class="icon-btn menu-btn" data-action="menu" aria-label="Open guide navigation" aria-controls="sidebar" aria-expanded="false">${icon('menu')}</button><div class="breadcrumbs"><a class="crumb-first" href="${parent[0]}">${parent[1]}</a>${icon('chevron')}<span>${esc(title)}</span></div></div><div class="tools">${helpButton(pageHelpKey(),'Help')}<button class="icon-btn" data-action="search" aria-label="Search guide" data-tip="Search the readings and resources. You can also press Control or Command K.">${icon('search')}</button><button class="icon-btn type-btn" data-action="font" aria-label="Change reading text size" data-tip="Cycle through three reading sizes. Your preference saves in this browser."><span style="font-family:Georgia;font-size:17px">Aa</span></button>${c?`<button class="icon-btn focus-btn" data-action="focus" aria-label="Toggle focused reading" aria-pressed="${state.focus}" data-tip="Hide the side navigation while reading. Select this button again to bring it back.">${icon('focus')}</button>`:''}<button class="icon-btn" data-action="theme" aria-label="Change theme" data-tip="Switch between a light and dark background.">${icon('moon')}</button><button class="icon-btn share-btn" data-action="share" aria-label="Copy a link to this page" data-tip="Copy a link to this page. A local HTML file must be shared as a file, not as a web address.">${icon('share')}</button></div><div class="reading-progress" id="reading-progress"></div>`;
}

function renderHome(){
 const next=CHAPTERS.find(c=>c.id===state.last&&!state.done.includes(c.id))||CHAPTERS.find(c=>!state.done.includes(c.id))||CHAPTERS[0];
 return `<div class="page home-page gf-home"><header class="gf-book-intro"><div class="gf-book-kicker"><span class="eyebrow">Write.law · Joe Regalia</span><span>For lawyers and law students</span></div><h1>The AI-Enabled Lawyer</h1><p class="gf-deck">How we use AI changes the legal work we can do.</p><div class="gf-intro-columns"><div><p>Law is made of language. Our tools once helped us find and move the words; now they can help produce the analysis and argument inside them. That gives us more to consider than how quickly we can finish a draft.</p><p>This guide collects my approach to that work. It begins with the judgment we bring to a problem, then develops the methods for writing, thinking, and working with AI. It also asks what becomes possible when lawyers can design better processes, build useful tools, and serve people whom the old approach left behind.</p></div><div class="gf-reading-note"><h2>Read it as a guide and return to it as a reference.</h2><p>The chapters contain the explanations, frameworks, and worked examples. You can follow them in order or choose the subject you need below. Exercises and worksheets support the reading; nothing needs to be completed to reach the teaching.</p><div class="actions"><a class="button primary" href="#/read/${next.id}">${state.last?'Continue reading':'Begin reading'} ${icon('arrow')}</a><a class="text-btn" href="#/chapters">View the contents ${icon('book')}</a></div></div></div></header><section class="gf-home-contents" aria-label="All chapters"><div class="section-heading"><div><span class="eyebrow">The complete guide</span><h2>Choose a chapter.</h2><p>The four parts follow the work from independent judgment to the systems and services we build around it.</p></div></div>${guideContents(true)}</section><aside class="gf-companion-footer"><h2>Optional resources for putting the ideas to work</h2><p>The <a href="#/labs">exercises</a> let you try the passages and problems discussed in the chapters. <a href="#/templates">Templates and worksheets</a> help you prepare an assignment of your own. Your entries appear in <a href="#/notebook">My saved work</a> and stay in this browser; use fictional or non-sensitive information.</p></aside>${footer()}</div>`;
}
function renderChapters(){return `<div class="page gf-contents-page"><header class="page-heading"><span class="eyebrow">The complete reading guide</span><h1>Contents</h1><p>Each chapter develops the ideas through explanations and worked examples. Read straight through or consult a subject when you need it. The exercises are optional, and no form or quiz is required to read the guide.</p>${helpButton('chapters','Help with the reading')}</header><nav class="gf-part-links" aria-label="Jump to a part">${PARTS.map((p,i)=>`<a href="#/chapters?part=${i}">${p.name}</a>`).join('')}</nav>${guideContents()}${footer()}</div>`;}
function labCard(l){return `<article class="feature-card resource-card"><div class="between"><span class="resource-kind ${resourceIsExercise(l)?'exercise-kind':''}">${resourceType(l.id)}</span>${helpButton(l.id,'Instructions for '+l.title,true)}</div><a class="resource-main" href="#/lab/${l.id}"><span class="feature-icon">${icon(l.icon)}</span><h3>${l.title}</h3><p>${l.desc}</p><div class="between"><span class="small">About ${l.time} ${resourceIsExercise(l)?'· Material supplied':'· Use a non-sensitive example'}</span>${icon('arrow')}</div></a></article>`;}

function renderQuiz(c){const picked=state.quiz[c.id],answered=Number.isInteger(picked);return `<div class="quiz" id="quiz-${c.id}"><span class="eyebrow">Check your understanding</span><h3>${c.quiz.q}</h3><div class="quiz-options">${c.quiz.a.map((a,i)=>`<button class="quiz-choice ${answered&&i===picked?(i===c.quiz.correct?'correct':'wrong'):''}" data-action="quiz" data-id="${c.id}" data-choice="${i}" aria-pressed="${picked===i}"><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${a}</span></button>`).join('')}</div><div class="quiz-feedback" aria-live="polite">${answered?`<strong>${picked===c.quiz.correct?'That answer matches the chapter’s explanation.':'Review the explanation before choosing again.'}</strong><p>${esc(c.quiz.why)}</p>${picked!==c.quiz.correct?'<p class="small muted" style="margin:8px 0 0">Choose again after reviewing the explanation.</p>':''}`:''}</div></div>`;}
function renderChapter(id){
 const c=CHAPTERS.find(c=>c.id===id);if(!c)return render404();const i=CHAPTERS.indexOf(c);currentChapter=id;state.last=id;saveState();
 const minutes=Math.max(3,Math.ceil(strip(c.sections.map(s=>s.html).join(' ')).split(/\s+/).length/200));
 const labs=LABS.filter(l=>l.chapter===id);
 return `<div class="page article-page gf-reading-page"><div class="chapter-meta"><span class="eyebrow">${PARTS[c.part].name} · Chapter ${num(i+1)}</span><span class="pill">${icon('clock')} About ${minutes} minutes of reading</span></div><header class="article-header"><h1 tabindex="-1">${c.title}</h1><p class="lede">${c.desc}</p></header><details class="mobile-page-contents"><summary>In this chapter</summary>${c.sections.map((s,j)=>`<a href="#/read/${id}?section=${j}">${s.h}</a>`).join('')}</details><div class="article-layout"><article class="prose"><div class="chapter-reading" data-reading-complete="true">${c.sections.map((s,j)=>`<section id="section-${j}" data-section-reading="${j}"><h2 class="section-title">${s.h}<button class="anchor" data-action="section-share" data-section="${j}" aria-label="Copy link to ${esc(s.h)}" data-tip="Copy a link to this section.">${icon('share')}</button></h2>${s.html}</section>`).join('')}</div><div class="gf-reading-end"><button class="button compact" data-action="complete" data-id="${id}">${icon(state.done.includes(id)?'check':'book')} ${state.done.includes(id)?'Marked as read':'Mark chapter as read'}</button><button class="text-btn" data-action="bookmark" data-id="${id}" aria-pressed="${state.bookmarks.includes(id)}">${icon('bookmark')} ${state.bookmarks.includes(id)?'Remove bookmark':'Bookmark this chapter'}</button></div><nav class="next-chapters" aria-label="Continue reading">${i>0?`<a href="#/read/${CHAPTERS[i-1].id}"><span class="eyebrow">Previous chapter</span><h3>${CHAPTERS[i-1].nav}</h3></a>`:`<a href="#/chapters"><span class="eyebrow">The full guide</span><h3>Return to the contents</h3></a>`}${i<CHAPTERS.length-1?`<a href="#/read/${CHAPTERS[i+1].id}"><span class="eyebrow">Next chapter</span><h3>${CHAPTERS[i+1].nav}</h3></a>`:`<a href="#/questions"><span class="eyebrow">Further inquiry</span><h3>Questions for the profession</h3></a>`}</nav><section class="gf-companions" aria-label="Optional chapter resources"><h2>Optional companions to this chapter</h2>${labs.length?`<p>These activities apply ideas explained above. They keep the same saved responses as earlier editions.</p><div class="gf-companion-links">${labs.map(l=>`<a href="#/lab/${l.id}">${esc(l.title)} ${icon('arrow')}</a>`).join('')}</div>`:'<p>You can keep a note or use the review question below. Neither is required to continue reading.</p>'}<details class="disclosure gf-optional-check"><summary>Review a question about this chapter</summary><div class="inside">${renderQuiz(c)}</div></details><details class="disclosure gf-note"><summary>Keep a personal note</summary><div class="inside">${field(`note-${id}`,'What would you use or question from this chapter?','Record an idea or a question you want to return to.',{hint:'Your note saves in My saved work. It is not sent to Write.law, an instructor, or an employer.'})}${id==='lawyer'?field('exercise-role','An assignment and the lawyer’s contribution','Describe an assignment you know and the judgment it requires.',{hint:'This is the same saved field used in the earlier opening chapter.'}):''}</div></details></section><details class="disclosure wl-chapter-sources"><summary>Sources and teaching notes</summary><div class="inside"><p>This chapter develops Joe Regalia’s supplied teaching materials. Worked comparisons are identified as source passages or as prepared additions; the explanations do not require using the companion activities.</p>${sourceChips(c)}${c.references?.length?`<div class="wl-source-links">${c.references.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ${icon('up')}</a>`).join('')}</div>`:''}<p><a class="inline-link" href="#/sources?scope=coverage">Read the source-coverage and editorial notes.</a></p></div></details></article><aside class="toc" aria-label="On this page"><span class="eyebrow">In this chapter</span>${c.sections.map((s,j)=>`<a href="#/read/${id}?section=${j}" data-toc="${j}">${s.h}</a>`).join('')}<div class="toc-note">The complete explanation is in the reading. Activities and personal notes follow as optional companions.</div>${helpButton('read','Help with the chapter')}<button class="text-btn" data-action="share">${icon('share')} Copy chapter link</button></aside></div>${footer()}</div>`;
}
function renderLabs(){return `<div class="page"><header class="page-heading"><span class="eyebrow">Practice with supplied material</span><h1>Exercises</h1><p>Read the passage or fictional problem, make your own attempt, then open the comparison or discussion. You can work independently or use the exercises alongside a course or workshop.</p>${helpButton('exercises','How the exercises work')}</header><aside class="section-context"><p>The explanations are prepared teaching material, not AI-generated feedback about your answer. You do not need an AI account. To plan an assignment of your own, use <a class="inline-link" href="#/templates">Templates & worksheets</a>.</p></aside><section><h2 class="wl-group-title">Practice a writing decision.</h2><div class="feature-grid">${['fee','stonebridge','falcon','aiisms'].map(id=>labCard(LABS.find(l=>l.id===id))).join('')}</div></section><section><h2 class="wl-group-title">Practice directing the analysis.</h2><div class="feature-grid">${['priorities','graph'].map(id=>labCard(LABS.find(l=>l.id===id))).join('')}</div></section>${footer()}</div>`;}
function renderTemplates(){const groups=[['Decide how to begin.',['preflight','pause'],'Examine the proposed use and record your own assessment before seeking assistance.'],['Plan the work and its review.',['workorder','process','shipping'],'Specify the assignment or proposed change, including the evidence needed to judge whether it works.'],['Keep learning from experience.',['playbook','reflection'],'Record useful methods and revisit questions as your experience develops.']];return `<div class="page"><header class="page-heading"><span class="eyebrow">Resources for your own assignments</span><h1>Templates & worksheets</h1><p>Use these forms to prepare instructions or work through a decision. Most ask you to bring a fictional or non-sensitive example. They help organize the work; they do not perform the assignment or approve a use.</p>${helpButton('templates','Which resource should I use?')}</header><section class="template-options"><article><span class="eyebrow">Starting instructions</span><h2>Adapt a prompt for a particular task.</h2><p>Choose a request, replace the placeholders, and supply the permitted materials in the AI tool you use.</p><a class="button primary compact" href="#/prompts">Browse prompt templates ${icon('arrow')}</a></article><article><span class="eyebrow">A form for your instructions</span><h2>Prepare a prompt from your own brief.</h2><p>Explain the assignment in the form, then review and copy the assembled instructions. Nothing is sent to an AI model.</p><a class="button compact" href="#/lab/promptbuilder">Open the prompt builder ${icon('arrow')}</a></article></section>${groups.map(([title,ids,desc])=>`<section><div class="section-heading"><div><h2>${title}</h2><p>${desc}</p></div></div><div class="feature-grid">${ids.map(id=>labCard(LABS.find(l=>l.id===id))).join('')}</div></section>`).join('')}${footer()}</div>`;}
function renderLab(id){const l=LABS.find(l=>l.id===id);if(!l)return render404();return `<div class="page activity-page"><header class="page-heading"><span class="eyebrow">${resourceType(id)} · About ${esc(l.time)}</span><h1>${l.title}</h1><p>${l.desc}</p></header><div class="activity-links"><a class="text-btn" href="#/read/${l.chapter}">${icon('book')} Read the related chapter</a><a class="text-btn" href="${resourceIsExercise(l)?'#/labs':'#/templates'}">${resourceIsExercise(l)?'All exercises':'All templates & worksheets'} ${icon('arrow')}</a><span class="save-status">${storageOK?'Entries save in this browser':'Storage unavailable: download before leaving'}</span></div>${resourceIntro(id)}<div data-widget="${id}"></div>${resourceEnd(id)}${footer()}</div>`;}
function renderPrompts(){return `<div class="page"><header class="page-heading"><span class="eyebrow"><a href="#/templates">Templates & worksheets</a> / Prompt templates</span><h1>Prompts to adapt</h1><p>Choose a request that fits your task. Read the instructions, replace every bracketed placeholder, and supply the permitted materials in an approved AI tool. Copying a prompt here does not run AI.</p>${helpButton('prompts','How to use a prompt template')}</header><div class="section-context"><p>A saved template is a bookmark. To prepare and keep your own version, use the <a class="inline-link" href="#/lab/promptbuilder">prompt builder</a>.</p></div><div class="library-controls"><div class="chips" aria-label="Filter prompts">${['All','Learn','Analyze','Write','Verify','Build','Saved'].map(c=>`<button class="tab ${promptCategory===c?'active':''}" data-action="prompt-filter" data-category="${c}" aria-pressed="${promptCategory===c}">${({Learn:'Learning',Analyze:'Analysis',Write:'Writing',Verify:'Checking',Build:'Planning & testing'})[c]||c}</button>`).join('')}</div><label class="filter-input">${icon('search')}<span class="sr-only">Search prompt templates</span><input type="search" id="prompt-search" placeholder="Find a prompt…" value="${esc(promptQuery)}"></label></div><div class="prompt-grid" id="prompt-list">${renderPromptList()}</div>${footer()}</div>`;}

function renderPromptList(){const matches=PROMPTS.filter(p=>(promptCategory==='All'||p.category===promptCategory||(promptCategory==='Saved'&&state.favorites.includes(p.id)))&&(`${p.title} ${p.use} ${p.text}`.toLowerCase().includes(promptQuery.toLowerCase())));return matches.length?matches.map(p=>`<section class="prompt-card" id="prompt-${p.id}"><div class="between"><span class="pill">${({Learn:'Learning',Analyze:'Analysis',Write:'Writing',Verify:'Checking',Build:'Planning & testing'})[p.category]}</span><button class="icon-btn ${state.favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'Remove saved template:':'Save template:'} ${esc(p.title)}" aria-pressed="${state.favorites.includes(p.id)}" data-tip="Save a reference to this template in My saved work. This does not create an editable copy.">${icon('bookmark')}</button></div><h2>${p.title}</h2><p class="prompt-use">${p.use}</p><details class="disclosure prompt-instructions"><summary>Read the instructions to copy</summary><div class="inside"><pre>${esc(p.text)}</pre></div></details><div class="actions"><button class="button compact" data-action="copy-prompt" data-id="${p.id}">${icon('copy')} Copy prompt</button></div><div class="source-note">${p.source}</div></section>`).join(''):`<div class="empty" style="grid-column:1/-1">${icon('search')}<h2>${promptCategory==='Saved'?'No saved templates yet':'No matching templates'}</h2><p>${promptCategory==='Saved'?'Select All and use a template’s bookmark button to save it here. Your own drafted prompts appear separately in My saved work.':'Try a different word or category.'}</p></div>`;}

function renderGlossary(){return `<div class="page"><header class="page-heading"><span class="eyebrow">Reference</span><h1>Glossary</h1><p>Look up a term when you encounter it in the reading. Each explanation links to a chapter where the idea is used; you do not need to memorize the glossary before beginning.</p>${helpButton('glossary','How to use the glossary')}</header><div class="library-controls"><label class="filter-input">${icon('search')}<span class="sr-only">Filter glossary</span><input type="search" id="glossary-search" placeholder="Find a term or an idea…" value="${esc(glossaryQuery)}"></label><span class="small muted" id="glossary-count">${GLOSSARY.length} terms</span></div><div class="glossary-grid" id="glossary-list">${renderGlossaryList()}</div>${footer()}</div>`;}

function renderGlossaryList(){const a=GLOSSARY.filter(([t,d])=>`${t} ${d}`.toLowerCase().includes(glossaryQuery.toLowerCase())).sort((a,b)=>a[0].localeCompare(b[0]));const count=document.getElementById('glossary-count');if(count)count.textContent=`${a.length} terms`;return a.length?a.map(([t,d,c])=>`<section class="glossary-item"><h3>${t}</h3><p>${d}</p><a href="#/read/${c}">Read the related chapter ${icon('arrow')}</a></section>`).join(''):`<div class="empty" style="grid-column:1/-1">No matching terms. Try “sources,” “judgment,” or “agent.”</div>`;}
function renderSources(){return `<div class="page sources-page"><header class="page-heading"><span class="eyebrow">About the teaching</span><h1>Sources and teaching notes</h1><p>This Write.law guide develops Joe Regalia's teaching on AI and legal work for practicing lawyers and law students. The explanations connect the methods with supplied exercises and forms you can adapt.</p></header><div class="reference-prose"><h2>The frameworks answer different questions.</h2><p>Foundations, Systems, Building, and Leadership organize the reading. The five-question before-use check helps you decide whether a particular use is appropriate. The five-stage responsible-use process covers an assignment from initial thinking through review and improvement.</p><p>The six collaboration practices and ten prompting principles help with individual exchanges. The twelve-part agent work order specifies a larger assignment, including permissions and human decisions. The guide preserves those separate purposes rather than combining them into another numbered formula.</p><h2>The teaching materials are adapted for this edition.</h2><p>The original document titles and page references appear below. The public edition is an editorial adaptation, not a complete reproduction of each source. It removes semester-only directions from the main teaching, develops slide points into explanations, and adds instructions for using the activities. The original PDFs and client-branded slide images are not distributed here.</p></div><div class="source-grid">${SOURCES.map((s,i)=>`<section class="source-card" id="source-${s.id}"><span class="eyebrow">${i<4?'Teaching source':'Companion teaching module'} ${num(i+1)}${s.pages?` · ${s.pages} pages`:''}</span><h3>${esc(s.title)}</h3><p>${esc(s.note||s.description||'')}</p>${s.file?`<div class="source-file">${esc(s.file)}</div>`:''}</section>`).join('')}</div><div class="reference-prose"><h2>Practice examples are not legal determinations.</h2><p>The fee-table, Stonebridge, Falcon Medical, and employee-departure exercises preserve the supplied facts. Their worked comparisons and discussion were developed for the guide; they are not a supplied legal answer key. The employee-departure problem has no controlling law in the packet, so the activity concerns investigative priorities rather than who should win.</p><p>The software-vendor workflow is a fictional demonstration. It assumes that the lawyer has supplied the relevant governing-law analysis. Its responses are prewritten, and its controls illustrate approval decisions rather than operate a live AI system. The AI-isms activity examines writing habits; it is not an authorship detector.</p><h2>Primary references support the further explanations.</h2><p>These materials provide context for the professional and technical discussions. A technical article or model benchmark does not establish that a particular use is appropriate for your matter. Check the governing rules and the actual product before relying on it.</p><div class="wl-reference-list"><article><h3><a href="https://www.americanbar.org/content/dam/aba/administrative/professional_responsibility/ethics-opinions/aba-formal-opinion-512.pdf" target="_blank" rel="noopener noreferrer">ABA Formal Opinion 512</a></h3><p>The July 2024 opinion discusses generative AI under the Model Rules, including competence, confidentiality, communication, supervision, and fees. It recognizes that the necessary review depends on the tool and task. It does not replace jurisdiction-specific authority.</p></article><article><h3><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noopener noreferrer">Building effective agents</a></h3><p>Anthropic's account of workflow and agent patterns informs the distinction between a planned sequence and a system choosing actions. The vendor exercise is this guide's legal teaching example.</p></article><article><h3><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noopener noreferrer">Effective context engineering for AI agents</a></h3><p>This technical discussion explains why selecting and maintaining useful context matters in extended work. The guide applies the idea to current source versions, reviewed findings, and continuation records.</p></article><article><h3><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noopener noreferrer">NIST AI Risk Management Framework</a></h3><p>The voluntary framework and its Generative AI Profile provide a broader reference for managing organizational risk. Completing a worksheet in this guide does not amount to certification or compliance with the framework.</p></article></div><h2>Further reading on legal writing</h2><p>These Write.law articles develop the writing approach used here: explain what the reader needs, make the choices visible through examples, and revise the substance as well as the sentences.</p><div class="wl-source-links"><a href="https://write.law/blog/the-quest-to-take-legal-writing-from-art-to-science" target="_blank" rel="noopener noreferrer">The quest to take legal writing from art to science ${icon('up')}</a><a href="https://write.law/blog/level-up-your-law" target="_blank" rel="noopener noreferrer">Level up your law ${icon('up')}</a><a href="https://write.law/blog/power-of-words" target="_blank" rel="noopener noreferrer">The power of words ${icon('up')}</a><a href="https://write.law/blog/policing-policy" target="_blank" rel="noopener noreferrer">Policing policy ${icon('up')}</a></div><h2>Some source claims are not adopted as current guidance.</h2><p>The original materials include dated product names, capability descriptions, and statistics. This edition emphasizes concepts rather than treating those details as current recommendations. The source slide giving a specific data-retention limit and enforcement example does not supply supporting authority; the guide does not adopt those assertions as law.</p><p>The four-minute pause is a practice suggested in the teaching materials, not an established threshold for legal performance. The underlying classroom research described there concerned science students and does not by itself establish the same effect for lawyers. The earlier graphing discussion also did not have full access to the linked social-media article; this guide does not claim to reproduce it.</p><h2>Your entries remain in your browser.</h2><p>The application makes no AI calls and has no account, note-upload, grading, or analytics feature. Hosting requests may still be processed by the hosting provider. Your readable exports and backup files contain your entries, so keep them in an appropriate location. Use fictional or non-sensitive examples here.</p><p><a class="inline-link" href="#/help?topic=saving">Read how saving, backups, and different website addresses work.</a></p><p class="small muted">Public edition revised September 2026. Educational material; not authorization for a particular AI use or jurisdiction-specific legal advice.</p></div>${renderSourceCoverage()}${footer()}</div>`;}
function fieldLabel(key){const fixed={'pause-baseline':'Assessment saved before feedback','prompt-saved':'Your saved prompt version','prompt-saved-assignment':'Your saved prompt version','fee-choice':'Comparison version selected','pause-decision':'Decision about the feedback','pause-feedback':'Feedback received','pause-reason':'Reason for the decision','fee-reflection':'Which sentence you would use, and why','fee-open':'Fee-table comparison opened','priorities-open':'Fact-priority discussion opened','stonebridge-open':'Stonebridge comparison opened','falcon-open':'Falcon comparison opened'};if(fixed[key])return fixed[key];if(FIELD_LABELS[key])return FIELD_LABELS[key];if(key.startsWith('note-'))return 'Chapter note: '+(CHAPTERS.find(c=>c.id===key.slice(5))?.nav||key.slice(5));if(key.startsWith('order-'))return 'Agent work order: '+(ORDER_FIELDS.find(f=>`order-${f[0]}`===key)?.[1]||key);if(key.startsWith('reflection-')){const m=key.match(/^reflection-(\d+)-(\d+)-(start|mid|end)$/);if(m&&REFLECTIONS[+m[1]]?.questions[+m[2]])return `${({start:'Beginning',mid:'Midpoint',end:'End'})[m[3]]}: ${REFLECTIONS[+m[1]].questions[+m[2]]}`;}if(key.startsWith('playbook-'))return PLAYBOOK_FIELDS.find(f=>`playbook-${f[0]}`===key)?.[1]||key;return key.replace(/-/g,' ').replace(/^./,c=>c.toUpperCase());}
function savedTextEntries(){return Object.entries(state.fields).filter(([k,v])=>typeof v==='string'&&v.trim()&&!SELECT_CHOICES[k]&&k!=='fee-choice');}
function savedSelections(){return Object.entries(state.fields).filter(([k,v])=>(typeof v==='boolean'&&!k.endsWith('-open'))||(typeof v==='string'&&v.trim()&&(SELECT_CHOICES[k]||k==='fee-choice')));}
function selectionText(key,v){if(typeof v==='boolean')return v?'Checked':'Not checked';if(key==='fee-choice')return FEE_OPTIONS[Number(v)]?.label||String(v);return SELECT_CHOICES[key]?.[v]||String(v);}
function renderSavedSelections(){const selections=savedSelections(),answers=Object.entries(state.quiz);if(!selections.length&&!answers.length)return '';return `<section class="notebook-section"><h2>Your selections and chapter answers</h2><p>These record what you selected, not an independent assessment of the work. Return to an activity to see the explanation or change an answer.</p>${selections.length?`<details class="saved-group"><summary><span>Worksheet choices and checkboxes</span><span class="small">${selections.length} recorded</span></summary><div class="saved-group-body"><dl class="saved-selections">${selections.map(([k,v])=>`<div><dt><a href="${fieldRoute(k)}">${esc(fieldLabel(k))}</a></dt><dd>${esc(selectionText(k,v))}</dd></div>`).join('')}</dl></div></details>`:''}${answers.length?`<details class="saved-group"><summary><span>Chapter questions</span><span class="small">${answers.length} answered</span></summary><div class="saved-group-body">${answers.map(([id,pick])=>{const c=CHAPTERS.find(c=>c.id===id);return `<section class="saved-quiz"><h3><a href="#/read/${id}?section=quiz">${c.nav}</a></h3><p>${c.quiz.q}</p><p><strong>Your selection:</strong> ${esc(c.quiz.a[pick])}</p></section>`;}).join('')}</div></details>`:''}</section>`;}

function fieldRoute(key){if(key.startsWith('note-'))return '#/read/'+key.slice(5);if(key==='exercise-role')return '#/read/lawyer';const rules=[['order-','workorder'],['prompt-','promptbuilder'],['priority-','priorities'],['priorities-','priorities'],['pause-','pause'],['graph-','graph'],['fee-','fee'],['stonebridge-','stonebridge'],['falcon-','falcon'],['aiisms-','aiisms'],['process-','process'],['shipping-','shipping'],['reflection-','reflection'],['playbook-','playbook'],['preflight-','preflight']];return '#/lab/'+(rules.find(([p])=>key.startsWith(p))?.[1]||'playbook');}
function renderNotebook(){const notes=savedTextEntries(),groups=new Map();notes.forEach(([k,v])=>{const route=fieldRoute(k);let title=route.startsWith('#/read/')?'Chapter notes':LABS.find(l=>route==='#/lab/'+l.id)?.title||'Other saved entries';if(!groups.has(title))groups.set(title,[]);groups.get(title).push([k,v,route]);});const fieldCount=Object.keys(state.fields).length;
 return `<div class="page"><header class="page-heading"><span class="eyebrow">Your entries and bookmarks</span><h1>My saved work</h1><p>This page collects what you have written elsewhere in the guide. Notes and responses save in this browser; they are not sent to Write.law, an instructor, an employer, or an AI model.</p>${helpButton('notebook','How saving and backups work')}</header><section class="notebook-toolbar"><div class="between"><h2>Keep a copy of your work</h2><span class="save-status">${storageOK?'Browser storage is available':'Storage unavailable'}</span></div><p>Download readable notes to review outside the guide. Download a backup to restore your entries and progress in another browser. Different devices and site addresses do not share saved work automatically.</p><div class="data-actions"><button class="button primary compact" data-action="export-md">${icon('download')} Download readable notes</button><button class="button compact" data-action="export-json">${icon('download')} Download a backup</button><button class="button compact" data-action="import">${icon('upload')} Restore a backup</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><p class="small muted">Readable notes are a text file you can open outside the guide. A backup is a separate file used to restore saved work here. Use non-sensitive material and store downloaded files appropriately.</p></section>${!fieldCount&&!state.favorites.length&&!state.bookmarks.length&&!Object.keys(state.quiz).length&&!state.done.length?`<section class="empty notebook-empty"><h2>You have not saved any work yet.</h2><p>Write a chapter note or try an activity. Your responses will appear here automatically, so you do not need to fill in this page first.</p><a class="button compact" href="#/labs">Choose an exercise ${icon('arrow')}</a></section>`:''}<section class="notebook-section"><div class="section-heading"><div><h2>Your notes and responses</h2><p>Open a group to read or edit an entry. The linked activity shows the question and your other answers together.</p></div></div>${groups.size?[...groups].map(([title,entries])=>`<details class="saved-group"><summary><span>${esc(title)}</span><span class="small">${entries.length} ${entries.length===1?'entry':'entries'}</span></summary><div class="saved-group-body">${entries.map(([k,v,route])=>`<details class="disclosure"><summary>${esc(fieldLabel(k))}</summary><div class="inside"><label class="field" for="saved-${esc(k)}"><span>Edit your response</span><textarea id="saved-${esc(k)}" data-save="${esc(k)}" aria-label="Edit ${esc(fieldLabel(k))}">${esc(v)}</textarea></label><a class="text-btn" href="${route}">Return to the question ${icon('arrow')}</a></div></details>`).join('')}</div></details>`).join(''):`<p class="muted">Written responses will appear here when you add them to a chapter or activity.</p>`}</section>${renderSavedSelections()}<section class="notebook-section saved-reference-grid"><div><h2>Bookmarked chapters</h2>${state.bookmarks.length?state.bookmarks.map(id=>{const c=CHAPTERS.find(c=>c.id===id);return `<a class="saved-link" href="#/read/${id}">${c.nav} ${icon('arrow')}</a>`;}).join(''):'<p>Use “Bookmark chapter” at the end of a reading to keep a link here.</p>'}</div><div><h2>Saved prompt templates</h2>${state.favorites.length?state.favorites.map(id=>{const p=PROMPTS.find(p=>p.id===id);return `<details class="disclosure"><summary>${p.title}</summary><div class="inside"><pre>${esc(p.text)}</pre><button class="text-btn" data-action="copy-prompt" data-id="${id}">${icon('copy')} Copy prompt</button></div></details>`;}).join(''):'<p>Use the bookmark on a prompt template to save it. These references are separate from a prompt you write in the builder.</p><a class="text-btn" href="#/prompts">Browse templates '+icon('arrow')+'</a>'}</div></section><section class="notebook-section"><h2>Develop your personal playbook</h2><p>The playbook is a worksheet for drawing lessons from these entries. It does not automatically summarize your notes, and you do not have to complete it before using other resources.</p><a href="#/lab/playbook" class="button compact">Open the playbook worksheet ${icon('arrow')}</a></section><details class="disclosure"><summary>Reading progress · ${state.done.length} of ${CHAPTERS.length} chapters marked as read</summary><div class="inside"><p>These marks are for your own reference, not a measure of mastery.</p><div class="progress-checks">${CHAPTERS.map((c,i)=>`<div class="progress-row"><label><input type="checkbox" data-read="${c.id}" ${state.done.includes(c.id)?'checked':''}><span>${num(i+1)} &nbsp; ${c.nav}</span></label><a href="#/read/${c.id}" class="icon-btn" aria-label="Read ${esc(c.nav)}">${icon('arrow')}</a></div>`).join('')}</div></div></details><details class="disclosure manage-storage"><summary>Manage stored data</summary><div class="inside"><p>Clearing saved work removes entries, bookmarks, and progress from this browser. Download a backup first when you need to keep them. This does not affect any backup files you have already downloaded.</p><button class="button compact danger" data-action="reset-data">Clear this browser’s saved work</button></div></details>${footer()}</div>`;}

function renderHelp(){return `<div class="page help-page"><header class="page-heading"><span class="eyebrow">Getting around and keeping your work</span><h1>How to use this guide</h1><p>The chapters contain the complete guidance and worked examples. Read them in order or consult a subject. Exercises, worksheets, and personal notes are optional companions.</p></header><div class="help-page-layout"><nav class="help-contents" aria-label="Help topics"><a href="#/help?topic=areas">Choose an area</a><a href="#/help?topic=first">Begin a session</a><a href="#/help?topic=activities">Use an activity</a><a href="#/help?topic=saving">Save and restore work</a><a href="#/help?topic=controls">Use the reading controls</a><a href="#/help?topic=questions">Common questions</a></nav><div class="reference-prose"><section id="help-areas"><h2>Choose the area that fits the task.</h2><p><strong>Chapters</strong> explain the concepts and methods. The four subjects organize the reading: Foundations, Systems, Building, and Leadership. They are not separate types of resource or courses you need to complete.</p><p><strong>Exercises</strong> provide a passage or fictional scenario. Make an initial attempt, then examine prepared discussion. The chapters now show the worked examples directly. Separate exercises remain optional and keep their earlier saved responses.</p><p><strong>Templates & worksheets</strong> help with a task you bring. Prompt templates supply starting instructions. The prompt builder assembles instructions from your entries. Other forms help you plan and review the work. None runs AI or authorizes a use.</p><p><strong>My saved work</strong> collects your notes, responses, bookmarked chapters, and saved prompt templates. The playbook is a separate worksheet where you draw lessons from those entries in your own words.</p></section><section id="help-first"><h2>Begin with something you can examine.</h2><p>For an introduction, read the first chapter and continue through the guide. You can skip every optional activity and still receive the complete teaching. For a focused session, the homepage and navigation give you the complete chapter list by subject. Suggested times are estimates, not deadlines.</p><p>You can use the guide independently, in a course, or in a Write.law workshop. Follow any separate assignment or workplace requirements. A law student need not have a live client matter, and a practicing lawyer need not work through every exercise before using a relevant chapter.</p><a href="#/read/lawyer" class="button compact">Open the first chapter ${icon('arrow')}</a></section><section id="help-activities"><h2>Read the instructions before beginning an activity.</h2><p>The introduction tells you what to bring and what the activity produces. The Help button provides further instructions. Essential directions remain on the page; you do not have to discover a tooltip to understand the task.</p><p>Worked comparisons, annotations, and workflow responses are prewritten. The guide does not evaluate your writing with AI. A chapter answer records your selection and reveals the prepared explanation; it does not assess your overall competence.</p><p>When using a prompt or work order elsewhere, read the assembled instructions, replace remaining placeholders, and provide the permitted documents in the approved tool itself. Completing the form here does not configure that application's permissions.</p></section><section id="help-saving"><h2>Keep a backup of work you need.</h2><p>Your text and selections save in the current browser profile. They are not uploaded to Write.law or submitted to an instructor or employer. A warning appears if storage is unavailable. The workflow demonstration's current step and timer are temporary, but written reflections are saved.</p><p><strong>Download readable notes</strong> creates a text file for reading or sharing your entries. <strong>Download a backup</strong> creates a JSON file the guide can restore. Use a backup to move work to a different browser, device, or website address.</p><p><strong>Restoring a backup replaces the entries in the destination browser.</strong> Keep a backup of its current work first when you need both. Check the file's date before restoring an older set of answers.</p><p>Updates at the same website address retain the existing storage key and activity identifiers. Your earlier entries should remain available in the same browser profile. A new custom domain is a different address, so use the backup and restore controls to move work there. The old address will remain available.</p><p>Browser storage is not an approved client workspace. Use fictional or non-sensitive information. Someone using the same browser profile may be able to see the entries, and clearing browser data can remove them. The guide has no account recovery service.</p><a href="#/notebook" class="button compact">Open My saved work ${icon('arrow')}</a></section><section id="help-controls"><h2>Adjust the reading experience.</h2><div class="actions reading-settings"><button class="button compact" data-action="font">Aa · Change reading size</button><button class="button compact" data-action="theme">Change theme</button><button class="button compact" data-action="motion" aria-pressed="${state.motion}">${state.motion?'Use system motion preference':'Reduce motion'}</button></div><p>Use the search button or Control/Command K to search the guide. The Aa button changes the reading size. The theme button switches between light and dark. In a chapter, focused reading hides the navigation until you select the control again.</p><p>On a phone, the menu opens navigation and “In this chapter” opens the page contents. Help works by click, tap, or keyboard. Hovering or focusing a question-mark button shows a short explanation; Escape dismisses it. The guide follows your system's reduced-motion setting, and you can also reduce animation here.</p></section><section id="help-questions"><h2>Common questions</h2><details class="disclosure"><summary>Do I need an AI account?</summary><div class="inside"><p>No account is needed to read or try the prepared exercises. Using a prompt outside the guide requires access to an appropriate tool and permission for the particular use.</p></div></details><details class="disclosure"><summary>Will anyone see my answers?</summary><div class="inside"><p>The guide does not send your entries to Write.law, an instructor, or your organization. Someone using the same browser profile may see them. To submit work for a course or workshop, use the separately designated process.</p></div></details><details class="disclosure"><summary>Where did the exercises embedded in the chapters go?</summary><div class="inside"><p>The chapter now gives you the full explanation and worked comparison without requiring an attempt. Links after the reading open the optional exercises. Their earlier addresses and saved responses are unchanged.</p></div></details><details class="disclosure"><summary>Does a completed checklist mean the use is approved?</summary><div class="inside"><p>No. The forms organize your decisions and evidence. They cannot determine the applicable policy, verify your sources, or approve a tool for a client matter.</p></div></details><details class="disclosure"><summary>How do I use my work at another website address?</summary><div class="inside"><p>At the old address, open My saved work and download a backup. At the new address, open the same page and restore that file. First preserve any work already saved at the destination, because restoring replaces it.</p></div></details></section></div></div>${footer()}</div>`;}
function render404(){return `<div class="page"><div class="empty" style="margin:50px auto;max-width:700px">${icon('book')}<h1 style="font-family:Georgia;font-size:30px;margin-bottom:15px">That page is not in this edition.</h1><p>The link may be incomplete. The chapter outline and resource pages are still available.</p><a href="#/" class="button primary">Return to the field guide ${icon('arrow')}</a></div>${footer()}</div>`;}
function parseRoute(){const raw=(location.hash||'#/').slice(1);const [path,query='']=raw.split('?');const parts=path.split('/').filter(Boolean);const params=new URLSearchParams(query);if(!parts.length)return {type:'home',params};if(parts[0]==='read')return {type:'read',id:parts[1],params};if(parts[0]==='lab')return {type:'lab',id:parts[1],params};if(['chapters','labs','templates','prompts','glossary','notebook','sources','help','questions'].includes(parts[0]))return {type:parts[0],params};return {type:'404',params};}
function route(){hideGuideTip();closeGuideHelp();closeSidebar();if(tocObserver)tocObserver.disconnect();currentRoute=parseRoute();if(currentRoute.type==='prompts'&&currentRoute.params.get('prompt')){promptCategory='All';promptQuery='';}currentChapter=currentRoute.type==='read'&&CHAPTERS.some(c=>c.id===currentRoute.id)?currentRoute.id:null;const f={home:renderHome,chapters:renderChapters,templates:renderTemplates,help:renderHelp,read:()=>renderChapter(currentRoute.id),labs:renderLabs,lab:()=>renderLab(currentRoute.id),prompts:renderPrompts,glossary:renderGlossary,notebook:renderNotebook,sources:renderSources,questions:renderQuestions};document.getElementById('main').innerHTML=(f[currentRoute.type]||render404)();renderSidebar();renderTopbar();applyPreferences();hydrateWidgets();restoreFields();updateStorageWarning();const c=CHAPTERS.find(c=>c.id===currentChapter);document.title=`${c?c.nav:({home:'About the guide',chapters:'Contents',templates:'Templates & worksheets',help:'How to use this guide',lab:LABS.find(l=>l.id===currentRoute.id)?.title,labs:'Exercises',prompts:'Prompt templates',glossary:'Glossary',notebook:'My saved work',sources:'Sources & guide notes',questions:'Questions for the profession'})[currentRoute.type]||'Guide'} · Write.law AI Guide`;requestAnimationFrame(()=>{window.scrollTo({top:0,behavior:'instant'});const section=currentRoute.params.get('section'),source=currentRoute.params.get('source');if(section!==null){const target=section==='quiz'?document.getElementById(`quiz-${currentChapter}`):document.getElementById(`section-${section}`);if(target){const holder=target.closest('details');if(holder)holder.open=true;target.scrollIntoView({behavior:'instant',block:'start'});}}else if(currentRoute.type==='questions'&&currentRoute.params.has('group'))document.getElementById('questions-'+currentRoute.params.get('group'))?.scrollIntoView({behavior:'instant'});else if(currentRoute.type==='chapters'&&currentRoute.params.has('part'))document.getElementById('part-'+currentRoute.params.get('part'))?.scrollIntoView({behavior:'instant'});else if(source)document.getElementById(`source-${source}`)?.scrollIntoView({behavior:'instant'});else if(currentRoute.type==='help'&&currentRoute.params.get('topic'))document.getElementById('help-'+currentRoute.params.get('topic'))?.scrollIntoView({behavior:'instant'});else if(currentRoute.type==='prompts'&&currentRoute.params.get('prompt')){const target=document.getElementById('prompt-'+currentRoute.params.get('prompt'));if(target){const details=target.querySelector('details');if(details)details.open=true;target.scrollIntoView({behavior:'instant'});}}else{const title=document.querySelector('#main h1');if(title){title.setAttribute('tabindex','-1');title.focus({preventScroll:true});}}observeTOC();updateReadingProgress();});}
function restoreFields(){document.querySelectorAll('[data-save]').forEach(el=>{if(Object.prototype.hasOwnProperty.call(state.fields,el.dataset.save))el.value=value(el.dataset.save);});document.querySelectorAll('[data-check]').forEach(el=>el.checked=value(el.dataset.check)===true);}
function observeTOC(){if(!currentChapter)return;tocObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.toc a').forEach(a=>a.classList.toggle('current',a.dataset.toc===e.target.id.replace('section-','')));}});},{rootMargin:'-10% 0px -65% 0px',threshold:0});document.querySelectorAll('.prose>section').forEach(el=>tocObserver.observe(el));}
function updateReadingProgress(){const el=document.getElementById('reading-progress');if(!el)return;const height=document.documentElement.scrollHeight-window.innerHeight;el.style.width=currentChapter&&height>0?`${Math.min(100,Math.max(0,window.scrollY/height*100))}%`:'0%';}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),3200);}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.left='-9999px';document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw new Error('Copy unavailable');}toast('Copied to clipboard.');return true;}catch(e){toast('Clipboard access is blocked. Select the text and copy it directly.');return false;}}
function sharePage(section){if(!/^https?:$/.test(location.protocol)){toast('This is a local copy. Share the HTML file itself; a local page link will not open for someone else.');return;}copyText(pageLink(section));}
function pageLink(section){const url=new URL(location.href);if(section!==undefined&&currentChapter)url.hash=`/read/${currentChapter}?section=${section}`;return url.toString();}
function downloadFile(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportNotebook(){
 let text=`MY NOTES FROM THE AI-ENABLED LAWYER\nJoe Regalia · Write.law\nDownloaded ${new Date().toISOString().slice(0,10)}\n\nThese are your own entries and recorded selections. They are not legal advice or approval of an AI use.\n\nREADING PROGRESS\n\n${CHAPTERS.map(c=>`${state.done.includes(c.id)?'[Read]':'[Not marked as read]'} ${c.nav}`).join('\n')}\n\nWRITTEN RESPONSES\n\n`;
 savedTextEntries().forEach(([k,v])=>text+=`${fieldLabel(k)}\n${'-'.repeat(Math.min(fieldLabel(k).length,60))}\n${v}\n\n`);
 text+='RECORDED SELECTIONS\n\n';
 savedSelections().forEach(([k,v])=>text+=`${fieldLabel(k)}\n${selectionText(k,v)}\n\n`);
 text+='CHAPTER QUESTIONS\n\n';
 Object.entries(state.quiz).forEach(([id,pick])=>{const c=CHAPTERS.find(c=>c.id===id);text+=`${c.nav}\n${c.quiz.q}\nYour selection: ${c.quiz.a[pick]}\nPrepared explanation: ${c.quiz.why}\n\n`;});
 text+='BOOKMARKED CHAPTERS\n\n';
 state.bookmarks.forEach(id=>text+=CHAPTERS.find(c=>c.id===id).nav+'\n');
 text+='\nSAVED PROMPT TEMPLATES\n\n';
 state.favorites.forEach(id=>{const p=PROMPTS.find(p=>p.id===id);text+=`${p.title}\n\n${p.text}\n\nSource: ${p.source}\n\n`;});
 downloadFile('WriteLaw-AI-Guide-Notes.txt',text,'text/plain');toast('Your notes have been downloaded as a text file.');
}
async function importBackup(file){if(!file)return;if(file.size>2000000){toast('This backup is too large. Limit: 2 MB.');return;}try{const raw=JSON.parse(await file.text());if(raw.app!=='regalia-ai-field-guide'||raw.version!==1||!raw.state||typeof raw.state!=='object'||Array.isArray(raw.state))throw new Error('format');if(!confirm('Import this backup? It will replace the saved work in this browser. Export your existing work first if you need it.'))return;state=safeState(raw.state);saveState();route();toast('Backup imported into this browser.');}catch(e){toast('This is not a valid field-guide backup. No saved work was changed.');}}
function openSidebar(){if(state.focus&&currentRoute.type==='read'){state.focus=false;saveState();applyPreferences();return;}document.body.classList.add('sidebar-open');document.getElementById('main').inert=true;document.getElementById('topbar').inert=true;document.getElementById('sidebar').setAttribute('role','dialog');document.getElementById('sidebar').setAttribute('aria-modal','true');document.getElementById('sidebar').setAttribute('aria-label','Guide navigation');document.querySelector('[data-action=menu]')?.setAttribute('aria-expanded','true');document.querySelector('.sidebar .brand')?.focus();}
function closeSidebar(){const was=document.body.classList.contains('sidebar-open');document.body.classList.remove('sidebar-open');document.getElementById('main').inert=false;document.getElementById('topbar').inert=false;const sidebar=document.getElementById('sidebar');sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');sidebar.removeAttribute('aria-label');document.querySelector('[data-action=menu]')?.setAttribute('aria-expanded','false');if(was)document.querySelector('[data-action=menu]')?.focus();}
const SEARCH_INDEX=[];
function buildSearch(){CHAPTERS.forEach(c=>{SEARCH_INDEX.push({title:c.nav,group:PARTS[c.part].name,text:c.desc,href:`#/read/${c.id}`});c.sections.forEach((s,i)=>SEARCH_INDEX.push({title:s.h,group:c.nav,text:strip(s.html),href:`#/read/${c.id}?section=${i}`}));});READING_QUESTIONS.forEach((g,i)=>g[2].forEach(q=>SEARCH_INDEX.push({title:q,group:g[0],text:g[1],href:`#/questions?group=${i}`})));PROMPTS.forEach(p=>SEARCH_INDEX.push({title:p.title,group:'Optional prompt templates',text:p.text,href:`#/prompts?prompt=${p.id}`}));GLOSSARY.forEach(([t,d,c])=>SEARCH_INDEX.push({title:t,group:'Glossary',text:d,href:`#/read/${c}`}));LABS.forEach(l=>SEARCH_INDEX.push({title:l.title,group:'Optional companion',text:l.desc,href:`#/lab/${l.id}`}));}
function openSearch(){closeSidebar();const dialog=document.getElementById('search-dialog');if(!dialog.open)dialog.showModal();const input=document.getElementById('global-search');input.value='';searchSelection=0;renderSearch('');input.focus();}
function highlight(text,query){if(!query)return esc(text);const lower=text.toLowerCase();const i=lower.indexOf(query.toLowerCase());return i<0?esc(text):esc(text.slice(0,i))+'<mark>'+esc(text.slice(i,i+query.length))+'</mark>'+esc(text.slice(i+query.length));}
function renderSearch(q){const terms=q.toLowerCase().trim().split(/\s+/).filter(Boolean);searchMatches=terms.length?SEARCH_INDEX.map(x=>{const text=`${x.title} ${x.group} ${x.text}`.toLowerCase();const matches=terms.every(t=>text.includes(t));return {...x,score:matches?terms.reduce((n,t)=>n+(x.title.toLowerCase().includes(t)?12:0)+(x.group.toLowerCase().includes(t)?3:0)+1,0)+(x.href.startsWith('#/read/')?2:0):0};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,20):['lawyer','method','graphing','writing'].map(id=>{const c=CHAPTERS.find(c=>c.id===id);return {title:c.title,group:PARTS[c.part].name,text:c.desc,href:`#/read/${id}`};});searchSelection=0;document.getElementById('search-results').innerHTML=searchMatches.length?searchMatches.map((m,i)=>{const idx=m.text.toLowerCase().indexOf(terms[0]||'');const start=Math.max(0,idx-60);const snippet=(start?'…':'')+m.text.slice(start,start+175)+(m.text.length>start+175?'…':'');return `<a class="search-result ${i===0?'selected':''}" href="${m.href}" data-search-result="${i}"><span class="eyebrow">${esc(m.group)}</span><strong>${highlight(m.title,q)}</strong><p>${highlight(snippet,q)}</p></a>`;}).join(''):`<div class="search-empty">No matching passages. Try fewer words or a related idea, such as “missing evidence,” “NDA,” “harness,” or “thinking risk.”</div>`;document.getElementById('search-status').textContent=`${searchMatches.length} ${terms.length?'results':'suggestions'}`;}
function moveSearch(delta){if(!searchMatches.length)return;searchSelection=(searchSelection+delta+searchMatches.length)%searchMatches.length;document.querySelectorAll('.search-result').forEach((el,i)=>el.classList.toggle('selected',i===searchSelection));document.querySelector(`.search-result[data-search-result="${searchSelection}"]`)?.scrollIntoView({block:'nearest'});}
function goSearch(){const m=searchMatches[searchSelection];if(m){document.getElementById('search-dialog').close();if(location.hash===m.href)route();else location.hash=m.href;}}
function toggleSaved(key,id){state[key]=state[key].includes(id)?state[key].filter(x=>x!==id):[...state[key],id];saveState();}
document.addEventListener('click',async e=>{
 if(e.target.closest('.skip-link')){e.preventDefault();document.getElementById('main').focus();window.scrollTo({top:0,behavior:'instant'});return;}
 const searchResult=e.target.closest('[data-search-result]');if(searchResult){document.getElementById('search-dialog').close();if(searchResult.getAttribute('href')===location.hash)route();return;}
 const toc=e.target.closest('[data-toc]');if(toc){e.preventDefault();const id=toc.dataset.toc;const target=id==='quiz'?document.getElementById(`quiz-${currentChapter}`):document.getElementById(`section-${id}`);target?.scrollIntoView({behavior:state.motion?'instant':'smooth'});history.replaceState(null,'',toc.href);return;}
 const copy=e.target.closest('[data-copy-parent]');if(copy){await copyText(copy.closest(copy.dataset.copyParent)?.querySelector('pre')?.textContent||'');return;}
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 if(handleWidgetAction(action,el))return;
 if(action==='search')openSearch();
 else if(action==='close-search')document.getElementById('search-dialog').close();
 else if(action==='menu')document.body.classList.contains('sidebar-open')?closeSidebar():openSidebar();
 else if(action==='close-menu')closeSidebar();
 else if(action==='theme'){state.theme=state.theme==='light'?'dark':'light';saveState();applyPreferences();}
 else if(action==='font'){state.font=state.font===17?19:state.font===19?16:17;saveState();applyPreferences();toast(`Reading size: ${state.font}px.`);}
 else if(action==='focus'){state.focus=!state.focus;saveState();applyPreferences();}
 else if(action==='motion'){state.motion=!state.motion;saveState();route();toast(state.motion?'Motion reduced.':'Motion follows your system preference.');}
 else if(action==='share')sharePage();
 else if(action==='section-share')sharePage(el.dataset.section);
 else if(action==='quiz'){const c=CHAPTERS.find(c=>c.id===el.dataset.id);state.quiz[c.id]=Number(el.dataset.choice);saveState();const wrap=document.getElementById(`quiz-${c.id}`);wrap.outerHTML=renderQuiz(c);document.querySelector(`#quiz-${c.id} [data-choice="${state.quiz[c.id]}"]`)?.focus({preventScroll:true});}
 else if(action==='complete'){toggleSaved('done',el.dataset.id);el.innerHTML=`${icon(state.done.includes(el.dataset.id)?'check':'book')} ${state.done.includes(el.dataset.id)?'Marked as read':'Mark chapter as read'}`;renderSidebar();toast(state.done.includes(el.dataset.id)?'Chapter marked as read.':'Chapter marked as unread.');}
 else if(action==='bookmark'){toggleSaved('bookmarks',el.dataset.id);el.innerHTML=`${icon('bookmark')} ${state.bookmarks.includes(el.dataset.id)?'Bookmarked':'Bookmark chapter'}`;el.setAttribute('aria-pressed',state.bookmarks.includes(el.dataset.id));}
 else if(action==='favorite'){toggleSaved('favorites',el.dataset.id);document.getElementById('prompt-list').innerHTML=renderPromptList();toast(state.favorites.includes(el.dataset.id)?'Template saved in My saved work.':'Template removed from My saved work.');}
 else if(action==='prompt-filter'){promptCategory=el.dataset.category;document.querySelectorAll('[data-action=prompt-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.category===promptCategory);b.setAttribute('aria-pressed',b.dataset.category===promptCategory);});document.getElementById('prompt-list').innerHTML=renderPromptList();}
 else if(action==='copy-prompt')copyText(PROMPTS.find(p=>p.id===el.dataset.id)?.text||'');
 else if(action==='export-md')exportNotebook();
 else if(action==='export-json'){downloadFile('WriteLaw-AI-Guide-Backup.json',JSON.stringify({app:'regalia-ai-field-guide',version:1,exported:new Date().toISOString(),state},null,2),'application/json');toast('Backup exported. It includes your saved work.');}
 else if(action==='import')document.getElementById('import-file').click();
 else if(action==='reset-data'){if(confirm('Permanently clear this browser’s notes, worksheets, saved prompts, and reading progress? Export a backup first if you need it.')){state=safeState({theme:state.theme,font:state.font});saveState();route();toast('Saved work cleared from this browser.');}}
});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-save]')){setField(el.dataset.save,el.value);onWidgetInput(el.dataset.save,el);}if(el.id==='global-search')renderSearch(el.value);if(el.id==='prompt-search'){promptQuery=el.value;document.getElementById('prompt-list').innerHTML=renderPromptList();}if(el.id==='glossary-search'){glossaryQuery=el.value;document.getElementById('glossary-list').innerHTML=renderGlossaryList();}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('select[data-save]')){setField(el.dataset.save,el.value);onWidgetInput(el.dataset.save,el);}if(el.matches('[data-check]')){setField(el.dataset.check,el.checked);onWidgetInput(el.dataset.check,el);}if(el.matches('[data-read]')){const id=el.dataset.read;state.done=el.checked?[...new Set([...state.done,id])]:state.done.filter(x=>x!==id);saveState();renderSidebar();const count=document.querySelector('.notebook-stats .pill');if(count)count.textContent=`${state.done.length} / 16 chapters read`;}if(el.id==='import-file')importBackup(el.files?.[0]);});
document.addEventListener('keydown',e=>{const dialog=document.getElementById('search-dialog');if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();dialog.open?dialog.close():openSearch();return;}if(dialog.open){if(e.key==='ArrowDown'){e.preventDefault();moveSearch(1);}if(e.key==='ArrowUp'){e.preventDefault();moveSearch(-1);}if(e.key==='Enter'&&e.target.id==='global-search'){e.preventDefault();goSearch();}return;}if(document.body.classList.contains('sidebar-open')){if(e.key==='Escape'){e.preventDefault();closeSidebar();}if(e.key==='Tab'){const links=[...document.querySelectorAll('.sidebar a,.sidebar button')];const first=links[0],last=links.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}else if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();openSearch();}});
window.addEventListener('hashchange',route);
window.addEventListener('scroll',updateReadingProgress,{passive:true});
window.addEventListener('resize',()=>{if(innerWidth>780)closeSidebar();updateReadingProgress();});
window.addEventListener('beforeunload',()=>{try{localStorage.setItem(APP_KEY,JSON.stringify(state));}catch(e){}});
document.getElementById('search-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
